int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long x1, y1, x2, y2;
    if (!(cin >> x1 >> y1 >> x2 >> y2)) return 0;
    long long x, y;
    cin >> x >> y;

    long long dx = x2 - x1;
    long long dy = y2 - y1;

    // Check parity: dx and dy must have same parity as 0 (since moves change parity together)
    if ((dx + dy) % 2 != 0) {
        cout << "NO\n";
        return 0;
    }

    // We need to solve:
    // dx = x*(a - b) + y*(c - d)
    // dy = y*(a - b) + x*(d - c)
    // where a,b,c,d are integers (can be negative, representing direction).
    // Let p = a - b, q = c - d.
    // Then:
    // dx = x*p + y*q
    // dy = y*p + x*(-q)  (since d - c = -q)
    // => dy = y*p - x*q
    //
    // Solve for p and q:
    // Adding: dx + dy = (x + y)*p  => p = (dx + dy)/(x + y)
    // Subtracting: dx - dy = (x - y)*q => q = (dx - dy)/(x - y) if x != y
    //
    // Special case x == y:
    // Then moves are:
    // (x, x), (-x, -x), (x, -x), (-x, x)
    // Reachable points must satisfy:
    // dx and dy are multiples of x, and (dx/x + dy/x) even.

    if (x == y) {
        if (dx % x != 0 || dy % x != 0) {
            cout << "NO\n";
            return 0;
        }
        long long sx = dx / x;
        long long sy = dy / x;
        // From combinations of (1,1),(-1,-1),(1,-1),(-1,1),
        // sx + sy must be even.
        if ((sx + sy) % 2 == 0) cout << "YES\n";
        else cout << "NO\n";
        return 0;
    }

    long long sum = x + y;
    long long diff = x - y;

    if ((dx + dy) % sum != 0) {
        cout << "NO\n";
        return 0;
    }
    long long p = (dx + dy) / sum;

    if ((dx - dy) % diff != 0) {
        cout << "NO\n";
        return 0;
    }
    long long q = (dx - dy) / diff;

    // p and q can be any integers; no further constraints.
    cout << "YES\n";
    return 0;
}

